using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.Linq;
using System.Text;

namespace SnapshotGenerator;

[Generator]
public class SnapshotSourceGenerator : IIncrementalGenerator
{
    private const string AttributeSource = """
            // <auto-generated/>
            #pragma warning disable
            #nullable enable

            using System;

            namespace SnapshotGenerator.Attributes
            {
                /// <summary>
                /// Génère automatiquement un Snapshot et les méthodes de comparaison (Dirty Checking) pour cette entité.
                /// </summary>
                [AttributeUsage(AttributeTargets.Class, Inherited = false, AllowMultiple = false)]
                internal sealed class SnapshotAttribute : Attribute 
                { 
                }
            }
            """;

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(ctx => ctx.AddSource("SnapshotAttribute.g.cs", SourceText.From(AttributeSource, Encoding.UTF8)));

        IncrementalValuesProvider<INamedTypeSymbol?> provider = context.SyntaxProvider
            .CreateSyntaxProvider(
                predicate: (s, _) => IsClassWithAttribute(s),
                transform: (ctx, _) => GetClassSymbol(ctx))
            .Where(m => m != null);

        // Collecter tous les symboles pour pouvoir détecter les propriétés avec [Snapshot]
        IncrementalValueProvider<ImmutableArray<INamedTypeSymbol>> collected = provider
            .Where(s => s != null)
            .Select((s, _) => s!)
            .Collect();

        context.RegisterSourceOutput(collected, (spc, classSymbols) =>
        {
            var snapshotTypes = new HashSet<string>(
                classSymbols.Select(s => s.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat)));

            foreach (INamedTypeSymbol classSymbol in classSymbols)
            {
                string code = GenerateSnapshotCode(classSymbol, snapshotTypes);
                spc.AddSource($"{classSymbol.Name}.Snapshot.g.cs", SourceText.From(code, Encoding.UTF8));
            }
        });
    }

    private bool IsClassWithAttribute(SyntaxNode node)
    {
        return node is ClassDeclarationSyntax c && c.AttributeLists.Count > 0;
    }

    private INamedTypeSymbol? GetClassSymbol(GeneratorSyntaxContext context)
    {
        var classDeclaration = (ClassDeclarationSyntax)context.Node;
        ISymbol? symbol = context.SemanticModel.GetDeclaredSymbol(classDeclaration);

        if (symbol is null)
        {
            return null;
        }

        bool hasAttribute = symbol.GetAttributes().Any(ad =>
            ad.AttributeClass?.Name == "SnapshotAttribute" ||
            ad.AttributeClass?.Name == "Snapshot");

        return (INamedTypeSymbol?)(hasAttribute ? symbol : null);
    }

    private string GenerateSnapshotCode(INamedTypeSymbol classSymbol, HashSet<string> snapshotTypes)
    {
        string namespaceName = classSymbol.ContainingNamespace.ToDisplayString();
        string className = classSymbol.Name;
        string visibility = classSymbol.DeclaredAccessibility.ToString().ToLowerInvariant();

        // Récupérer les propriétés scalaires
        var scalarProperties = classSymbol.GetMembers().OfType<IPropertySymbol>()
            .Where(p => !p.IsStatic && !p.IsIndexer && IsScalarProperty(p))
            .ToList();

        // Récupérer les propriétés complexes qui ont [Snapshot]
        var snapshotProperties = classSymbol.GetMembers().OfType<IPropertySymbol>()
            .Where(p => !p.IsStatic && !p.IsIndexer && IsSnapshotProperty(p, snapshotTypes))
            .ToList();

        // Récupérer les propriétés ValueObject (qui ont [GenerateValueObject])
        var valueObjectProperties = classSymbol.GetMembers().OfType<IPropertySymbol>()
            .Where(p => !p.IsStatic && !p.IsIndexer && IsValueObjectProperty(p))
            .ToList();

        // Récupérer les backing fields de type List<simple> (ex: List<string>, List<int>)
        var simpleListFields = classSymbol.GetMembers().OfType<IFieldSymbol>()
            .Where(f => !f.IsStatic && IsSimpleListField(f))
            .ToList();

        // 1. Définition des paramètres du Record pour les propriétés scalaires
        string recordProps = string.Join(",\n            ",
            scalarProperties.Select(p => $"{p.Type.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat)} {p.Name}"));

        // 1b. Ajouter les listes simples au record (stockées comme List<T>)
        if (simpleListFields.Count > 0)
        {
            string listRecordProps = string.Join(",\n            ",
                simpleListFields.Select(f => $"{f.Type.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat)} {GetSnapshotFieldName(f)}"));
            recordProps = string.IsNullOrEmpty(recordProps)
                ? listRecordProps
                : $"{recordProps},\n            {listRecordProps}";
        }

        // 2. Assignation dans le constructeur
        string constructorArgs = string.Join(",\n                ",
            scalarProperties.Select(p => $"this.{p.Name}"));

        // 2b. Ajouter les listes simples (copie avec ToList())
        if (simpleListFields.Count > 0)
        {
            string listArgs = string.Join(",\n                ",
                simpleListFields.Select(f => $"this.{f.Name}.ToList()"));
            constructorArgs = string.IsNullOrEmpty(constructorArgs)
                ? listArgs
                : $"{constructorArgs},\n                {listArgs}";
        }

        // 3. Logique de comparaison pour GetChanges
        var comparisonLogicBuilder = new StringBuilder();
        foreach (IPropertySymbol p in scalarProperties)
        {
            string typeName = p.Type.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);
            comparisonLogicBuilder.AppendLine($$"""
                        if (!EqualityComparer<{{typeName}}>.Default.Equals(this.{{p.Name}}, _originalState.{{p.Name}}))
                        {
                            changes.Add(nameof({{p.Name}}));
                        }
            """);
        }

        // 3b. Comparaison des listes simples (SequenceEqual)
        foreach (IFieldSymbol f in simpleListFields)
        {
            string snapshotName = GetSnapshotFieldName(f);
            comparisonLogicBuilder.AppendLine($$"""
                        if (!this.{{f.Name}}.SequenceEqual(_originalState.{{snapshotName}}))
                        {
                            changes.Add("{{f.Name}}");
                        }
            """);
        }

        // 4. Génération du dictionnaire pour GetSnapshot (propriétés scalaires)
        var snapshotScalarBuilder = new StringBuilder();
        foreach (IPropertySymbol p in scalarProperties)
        {
            snapshotScalarBuilder.AppendLine($"                {{ nameof({p.Name}), this.{p.Name} }},");
        }

        // 4b. Ajouter les listes simples au snapshot
        foreach (IFieldSymbol f in simpleListFields)
        {
            snapshotScalarBuilder.AppendLine($"                {{ \"{f.Name}\", this.{f.Name}.ToList() }},");
        }

        // 5. Génération du dictionnaire pour GetSnapshot (propriétés complexes avec [Snapshot])
        var snapshotComplexBuilder = new StringBuilder();
        foreach (IPropertySymbol p in snapshotProperties)
        {
            snapshotComplexBuilder.AppendLine($$"""
                        if (this.{{p.Name}} != null)
                        {
                            snapshot[nameof({{p.Name}})] = this.{{p.Name}}.GetSnapshot(deepSearch);
                        }
            """);
        }

        // 5b. Génération du dictionnaire pour GetSnapshot (propriétés ValueObject)
        foreach (IPropertySymbol p in valueObjectProperties)
        {
            snapshotComplexBuilder.AppendLine($$"""
                        if (this.{{p.Name}} != null)
                        {
                            snapshot[nameof({{p.Name}})] = this.{{p.Name}};
                        }
            """);
        }

        // 6. Génération de l'hydratation en profondeur pour les propriétés [Snapshot]
        var deepHydrateBuilder = new StringBuilder();
        foreach (IPropertySymbol p in snapshotProperties)
        {
            deepHydrateBuilder.AppendLine($$"""
                        this.{{p.Name}}?.HydrateSnapshot(deepHydrate);
            """);
        }

        // 7. Génération de la détection des changements en profondeur (propriétés [Snapshot])
        var deepChangesBuilder = new StringBuilder();
        foreach (IPropertySymbol p in snapshotProperties)
        {
            deepChangesBuilder.AppendLine($$"""
                        if (this.{{p.Name}} != null && this.{{p.Name}}.HasChanges(deepSearch))
                        {
                            changes.Add(nameof({{p.Name}}));
                        }
            """);
        }

        // 7b. Génération de la détection des changements pour les ValueObject
        var valueObjectChangesBuilder = new StringBuilder();
        foreach (IPropertySymbol p in valueObjectProperties)
        {
            valueObjectChangesBuilder.AppendLine($$"""
                    if (this.{{p.Name}} != null && this.{{p.Name}}.HasChanges)
                    {
                        changes.Add(nameof({{p.Name}}));
                    }
            """);
        }

        // 8. Liste des propriétés complexes pour documentation
        string complexPropertiesComment = snapshotProperties.Count > 0
            ? $"/// Propriétés complexes avec [Snapshot]: {string.Join(", ", snapshotProperties.Select(p => p.Name))}"
            : "/// Aucune propriété complexe avec [Snapshot]";

        string valueObjectPropertiesComment = valueObjectProperties.Count > 0
            ? $"/// Propriétés ValueObject: {string.Join(", ", valueObjectProperties.Select(p => p.Name))}"
            : "/// Aucune propriété ValueObject";

        string simpleListFieldsComment = simpleListFields.Count > 0
            ? $"/// Listes simples trackées: {string.Join(", ", simpleListFields.Select(f => f.Name))}"
            : "/// Aucune liste simple trackée";

        return $$"""
        // <auto-generated/>
        #pragma warning disable
        #nullable enable

        using System;
        using System.Collections.Generic;
        using System.Linq;

        namespace {{namespaceName}}
        {
            {{visibility}} partial class {{className}}
            {
                private record SnapshotState(
                    {{recordProps}}
                );

                private SnapshotState? _originalState;

                /// <summary>
                /// Prend une photo de l'état actuel (à appeler après chargement BDD).
                /// </summary>
                /// <param name="deepHydrate">Si true, hydrate également les propriétés complexes qui ont [Snapshot].</param>
                public void HydrateSnapshot(bool deepHydrate = true)
                {
                    _originalState = new SnapshotState(
                        {{constructorArgs}}
                    );

                    if (deepHydrate)
                    {
        {{deepHydrateBuilder}}
                    }
                }

                /// <summary>
                /// Retourne la liste des noms de propriétés modifiées depuis l'hydratation.
                /// {{complexPropertiesComment}}
                /// {{valueObjectPropertiesComment}}
                /// {{simpleListFieldsComment}}
                /// </summary>
                /// <param name="deepSearch">Si true, vérifie également les changements dans les propriétés complexes avec [Snapshot].</param>
                public IReadOnlyList<string> GetChanges(bool deepSearch = false)
                {
                    if (_originalState == null)
                    {
                        return new List<string>();
                    }

                    List<string> changes = new List<string>();

        {{comparisonLogicBuilder}}

                    // Vérification des changements dans les propriétés ValueObject
        {{valueObjectChangesBuilder}}

                    if (deepSearch)
                    {
        {{deepChangesBuilder}}
                    }

                    return changes;
                }

                /// <summary>
                /// Vérifie si une propriété spécifique a changé.
                /// </summary>
                /// <param name="propertyName">Nom de la propriété à vérifier.</param>
                /// <param name="deepSearch">Si true, vérifie également dans les propriétés complexes.</param>
                public bool IsModified(string propertyName, bool deepSearch = false)
                {
                    if (_originalState == null)
                    {
                        return false;
                    }

                    return GetChanges(deepSearch).Contains(propertyName);
                }

                /// <summary>
                /// Vérifie si l'entité a des modifications.
                /// {{complexPropertiesComment}}
                /// {{valueObjectPropertiesComment}}
                /// </summary>
                /// <param name="deepSearch">Si true, vérifie également les changements dans les propriétés complexes avec [Snapshot].</param>
                public bool HasChanges(bool deepSearch = false) => GetChanges(deepSearch).Count > 0;

                /// <summary>
                /// Retourne un snapshot complet de l'objet sous forme de dictionnaire.
                /// {{complexPropertiesComment}}
                /// {{valueObjectPropertiesComment}}
                /// </summary>
                /// <param name="deepSearch">Si true, inclut les propriétés complexes qui ont également [Snapshot].</param>
                /// <returns>Dictionnaire contenant toutes les propriétés de l'objet.</returns>
                public Dictionary<string, object?> GetSnapshot(bool deepSearch = false)
                {
                    Dictionary<string, object?> snapshot = new Dictionary<string, object?>
                    {
        {{snapshotScalarBuilder}}
                    };

                    if (deepSearch)
                    {
        {{snapshotComplexBuilder}}
                    }

                    return snapshot;
                }

                /// <summary>
                /// Retourne le snapshot original hydraté sous forme de dictionnaire.
                /// </summary>
                /// <returns>Dictionnaire de l'état original ou null si non hydraté.</returns>
                public Dictionary<string, object?>? GetOriginalSnapshot()
                {
                    if (_originalState == null)
                    {
                        return null;
                    }

                    return new Dictionary<string, object?>
                    {
        {{string.Join("\n", scalarProperties.Select(p => $"                {{ nameof({p.Name}), _originalState.{p.Name} }},"))}}
        {{string.Join("\n", simpleListFields.Select(f => $"                {{ \"{f.Name}\", _originalState.{GetSnapshotFieldName(f)} }},"))}}
                    };
                }

                /// <summary>
                /// Retourne un snapshot JSON de l'objet.
                /// </summary>
                /// <param name="deepSearch">Si true, inclut les propriétés complexes.</param>
                /// <returns>JSON string du snapshot.</returns>
                public string GetSnapshotJson(bool deepSearch = false)
                {
                    return System.Text.Json.JsonSerializer.Serialize(GetSnapshot(deepSearch));
                }
            }
        }
        """;
    }

    private bool IsScalarProperty(IPropertySymbol p)
    {
        string typeName = p.Type.Name;

        if (typeName.Contains("List") || typeName.Contains("Collection") || typeName.Contains("IEnumerable"))
        {
            return false;
        }

        if (p.Type is INamedTypeSymbol namedType && namedType.IsGenericType)
        {
            if (namedType.OriginalDefinition.SpecialType == SpecialType.System_Nullable_T)
            {
                return true;
            }

            return false;
        }

        // Exclure les types complexes (classes référencées)
        if (p.Type.TypeKind == TypeKind.Class && p.Type.SpecialType == SpecialType.None && p.Type.Name != "String")
        {
            return false;
        }

        return true;
    }

    private bool IsSnapshotProperty(IPropertySymbol p, HashSet<string> snapshotTypes)
    {
        if (p.Type.TypeKind != TypeKind.Class || p.Type.SpecialType != SpecialType.None)
        {
            return false;
        }

        if (p.Type.Name == "String")
        {
            return false;
        }

        // Exclure les ValueObjects (ils sont traités séparément)
        if (IsValueObjectProperty(p))
        {
            return false;
        }

        // Vérifier si le type de la propriété a l'attribut [Snapshot]
        string fullTypeName = p.Type.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);
        return snapshotTypes.Contains(fullTypeName);
    }

    private bool IsValueObjectProperty(IPropertySymbol p)
    {
        if (p.Type.TypeKind != TypeKind.Class || p.Type.SpecialType != SpecialType.None)
        {
            return false;
        }

        if (p.Type.Name == "String")
        {
            return false;
        }

        // Vérifier si le type a l'attribut [GenerateValueObject]
        bool hasValueObjectAttribute = p.Type.GetAttributes().Any(a =>
            a.AttributeClass?.Name == "GenerateValueObjectAttribute" ||
            a.AttributeClass?.Name == "GenerateValueObject");

        if (hasValueObjectAttribute)
        {
            return true;
        }

        // Vérifier si le type hérite de ValueObject
        INamedTypeSymbol? baseType = p.Type.BaseType;
        while (baseType != null)
        {
            if (baseType.Name == "ValueObject")
            {
                // Vérifier aussi si le type a l'attribut (peut être sur la classe elle-même)
                return p.Type.GetAttributes().Any(a =>
                    a.AttributeClass?.Name == "GenerateValueObjectAttribute" ||
                    a.AttributeClass?.Name == "GenerateValueObject");
            }
            baseType = baseType.BaseType;
        }

        return false;
    }

    /// <summary>
    /// Detects backing fields of type List&lt;T&gt; where T is a simple type (string, int, etc.).
    /// These are typically private readonly fields like _gencods, _suppliersReferences.
    /// </summary>
    private bool IsSimpleListField(IFieldSymbol f)
    {
        if (f.Type is not INamedTypeSymbol namedType || !namedType.IsGenericType)
        {
            return false;
        }

        string typeName = namedType.OriginalDefinition.ToDisplayString();
        if (typeName != "System.Collections.Generic.List<T>")
        {
            return false;
        }

        // Check that the element type is a simple type (string, int, decimal, etc.)
        ITypeSymbol elementType = namedType.TypeArguments[0];
        if (elementType.SpecialType != SpecialType.None)
        {
            return true; // Built-in types (string, int, bool, etc.)
        }

        if (elementType.TypeKind == TypeKind.Enum)
        {
            return true;
        }

        return false;
    }

    /// <summary>
    /// Generates a snapshot-safe name for a backing field (e.g., _gencods -> _gencods_snapshot).
    /// </summary>
    private static string GetSnapshotFieldName(IFieldSymbol f) => $"{f.Name}_snapshot";
}
